/*
 * Home page of the documentation (docs/overrides/home.html).
 *
 * Progressive enhancement: renders the stage animation (profile, plan, run,
 * ask), the compare() leaderboard and the generated script from the JSON in
 * the data-home attribute of #sk-home. It does nothing on pages without
 * #sk-home. With navigation.instant, `document$` emits on every page change:
 * the previous instance is destroyed (animation frame, observers and
 * listeners) before a new one starts.
 *
 * The data is generated by tools/home_page/generate_home_data.py. The
 * structure follows the home page of the skforecast documentation.
 */
(function () {
  "use strict";

  var current = null;

  function init() {
    var root = document.getElementById("sk-home");
    if (!root || !root.getAttribute("data-home")) return null;
    var ALL = JSON.parse(root.getAttribute("data-home"));
    var DATA = ALL.hero;
    var cancelled = false, observers = [], timers = [];

    function $(id) { return document.getElementById(id); }
    var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    /* ---------- copy buttons ---------- */
    function copyButton(btn, text) {
      var label = btn.getAttribute("aria-label");
      btn.addEventListener("click", function () {
        var done = function () {
          btn.classList.add("copied");
          btn.setAttribute("aria-label", "Copied");
          timers.push(setTimeout(function () { btn.classList.remove("copied"); btn.setAttribute("aria-label", label); }, 1500));
        };
        try {
          navigator.clipboard.writeText(text).then(done, function () {});
        } catch (e) {}
      });
    }
    Array.prototype.forEach.call(root.querySelectorAll(".copy[data-copy]"), function (btn) {
      copyButton(btn, btn.getAttribute("data-copy"));
    });

    /* ---------- syntax highlight ---------- */
    var KEYWORDS = { from: 1, import: 1, None: 1, True: 1, False: 1, def: 1, return: 1, for: 1, in: 1, if: 1, as: 1 };
    function esc(t) { return t.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
    function wrap(cls, t) { return cls ? '<span class="' + cls + '">' + esc(t) + "</span>" : esc(t); }
    function hl(src) {
      var re = /(#[^\n]*)|("[^"\n]*"?|'[^'\n]*'?)|([A-Za-z_]\w*)|(\d+(?:\.\d+)?)|([()[\]{},.:=+\-*\/])/g;
      var out = "", last = 0, inFrom = false, m;
      while ((m = re.exec(src)) !== null) {
        out += esc(src.slice(last, m.index));
        last = re.lastIndex;
        var tok = m[0], cls = "";
        if (m[1]) cls = "tk-m";
        else if (m[2]) cls = "tk-s";
        else if (m[4]) cls = "tk-n";
        else if (m[5]) cls = "tk-p";
        else if (KEYWORDS[tok]) {
          cls = "tk-k";
          if (tok === "from") inFrom = true;
          if (tok === "import") inFrom = false;
        } else if (inFrom) {
          cls = "";                                   /* module path */
        } else {
          var rest = src.slice(last);
          if (/^[A-Z]/.test(tok)) cls = "tk-c";       /* class */
          else if (/^\s*\(/.test(rest)) cls = "tk-f"; /* function or method call */
          else if (tok === "f" && /^["']/.test(rest)) cls = "tk-s";  /* f-string prefix */
        }
        out += wrap(cls, tok);
      }
      return out + esc(src.slice(last));
    }

    /* ---------- chart geometry ---------- */
    var svg = $("chart");
    /* On narrow screens the chart is drawn on a narrower canvas with less history,
       so that its text keeps a readable size once the SVG is scaled down. */
    var narrow = svg.getBoundingClientRect().width < 640;
    var W = narrow ? 560 : 900;
    svg.setAttribute("viewBox", "0 0 " + W + " 400");
    var L = 46, R = W - 16, T = 34, B = 296, XB = 382;
    var dates = DATA.dates, yv = DATA.y, STEPS = DATA.steps;
    var te = dates.indexOf(DATA.train_end);
    var end = dates.length - 1;
    /* On narrow screens, three days of history instead of a week: the arc of
       lag 169 then starts outside the chart and is not drawn. */
    var start = narrow ? te - 72 : 0;
    var MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    var ymin = 0, ymax = 350;
    function sx(i) { return L + (i - start) / (end - start) * (R - L); }
    function sy(v) { return B - (v - ymin) / (ymax - ymin) * (B - T); }
    function el(tag, attrs, parent) {
      var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
      for (var k in attrs) e.setAttribute(k, attrs[k]);
      if (parent) parent.appendChild(e);
      return e;
    }
    function range(a, b) { var o = []; for (var k = a; k <= b; k++) o.push(k); return o; }
    function ease(t) { t = Math.max(0, Math.min(1, t)); return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }
    function clamp01(t) { return Math.max(0, Math.min(1, t)); }
    function linePath(xs, ys) {
      var d = "";
      for (var k = 0; k < xs.length; k++) d += (k ? "L" : "M") + xs[k].toFixed(1) + "," + ys[k].toFixed(1);
      return d;
    }
    /* partial path up to fractional progress p in [0,1] */
    function partial(idx, vals, p) {
      var n = idx.length;
      if (p <= 0 || n === 0) return "";
      var f = p * (n - 1), k = Math.floor(f), r = f - k;
      var xs = [], ys = [];
      for (var j = 0; j <= Math.min(k, n - 1); j++) { xs.push(sx(idx[j])); ys.push(sy(vals[j])); }
      if (k < n - 1 && r > 0) {
        xs.push(sx(idx[k] + r * (idx[k + 1] - idx[k])));
        ys.push(sy(vals[k] + r * (vals[k + 1] - vals[k])));
      }
      return xs.length > 1 ? linePath(xs, ys) : "";
    }

    var grid = $("g-grid");
    for (var v = 0; v <= 300; v += 100) {
      el("line", { x1: L, x2: R, y1: sy(v), y2: sy(v), "class": "g-grid" }, grid);
      el("text", { x: L - 10, y: sy(v) + 4, "text-anchor": "end", "class": "g-ax" }, grid).textContent = v;
    }
    el("text", { x: L - 10, y: T - 16, "text-anchor": "start", "class": "g-axlab" }, grid).textContent = "USERS PER HOUR";
    for (var i = start; i <= end; i++) {
      if (dates[i].slice(11) === "00:00") {
        el("line", { x1: sx(i), x2: sx(i), y1: XB - 18, y2: XB - 13, "class": "g-grid" }, grid);
        el("text", { x: sx(i), y: XB, "text-anchor": "middle", "class": "g-ax" }, grid).textContent =
          MONTHS[+dates[i].slice(5, 7) - 1] + " " + (+dates[i].slice(8, 10));
      }
    }

    /* horizon: the last 36 hours, held out from training */
    var hzx = sx(te - 0.5);
    var hz = $("g-hz"); hz.setAttribute("x", hzx); hz.setAttribute("y", T - 14); hz.setAttribute("width", R - hzx + 8); hz.setAttribute("height", B - T + 14);
    var hzl = $("g-hzline"); hzl.setAttribute("x1", hzx); hzl.setAttribute("x2", hzx); hzl.setAttribute("y1", T - 14); hzl.setAttribute("y2", B);
    /* labels anchored to the right edge: the held-out region is narrow */
    var hzlab = $("g-hzlab"); hzlab.setAttribute("x", R - 4); hzlab.setAttribute("y", T + 2); hzlab.setAttribute("text-anchor", "end");
    hzlab.textContent = narrow ? "HELD OUT, 36 H" : "HELD OUT, 36 HOURS";

    var histIdx = range(start, te - 1), histVal = histIdx.map(function (k) { return yv[k]; });
    var hzIdx = range(te - 1, end), actVal = hzIdx.map(function (k) { return yv[k]; });
    var nAll = end - start;

    /* ---------- profile: lag arcs ---------- */
    /* From the last training hour back to the lags of one day and one week
       found by the partial autocorrelation (25 and 169 on this data). */
    var arcs = [];
    var anchor = te - 1;
    [[25, "LAG 25, A DAY BACK"], [169, "LAG 169, A WEEK BACK"]].forEach(function (a) {
      var from = anchor - a[0];
      if (from < start || ALL.profile.pacf_lags.indexOf(a[0]) < 0) return;
      var x0 = sx(from), y0 = sy(yv[from]), x1 = sx(anchor), y1 = sy(yv[anchor]);
      var top = Math.max(T - 8, Math.min(y0, y1) - 40 - (x1 - x0) * 0.08);
      var g = el("g", { opacity: 0 }, $("g-arcs"));
      var path = el("path", { "class": "g-arc" }, g);
      var d0 = el("circle", { cx: x0, cy: y0, r: 4, "class": "g-arcdot" }, g);
      el("circle", { cx: x1, cy: y1, r: 4, "class": "g-arcdot" }, g);
      var lab = el("text", { x: (x0 + x1) / 2, y: top - 8, "text-anchor": "middle", "class": "g-arclab" }, g);
      lab.textContent = narrow && a[0] === 25 ? "LAG 25" : a[1];
      var cx = (x0 + x1) / 2, cy = 2 * top - (y0 + y1) / 2;
      arcs.push({ g: g, path: path, dot: d0, lab: lab, x0: x0, y0: y0, x1: x1, y1: y1, cx: cx, cy: cy });
    });
    /* quadratic Bezier drawn from the present back to the lag, up to progress p */
    function arcD(a, p) {
      var n = 32, d = "";
      for (var k = 0; k <= Math.round(n * p); k++) {
        var s = k / n, u = 1 - s;
        var x = u * u * a.x1 + 2 * u * s * a.cx + s * s * a.x0;
        var y = u * u * a.y1 + 2 * u * s * a.cy + s * s * a.y0;
        d += (k ? "L" : "M") + x.toFixed(1) + "," + y.toFixed(1);
      }
      return d;
    }

    /* ---------- plan: rolling windows ---------- */
    var wins = [];
    (ALL.plan.window_features || []).forEach(function (w, k) {
      var size = w.window_size, x0 = Math.max(L, sx(te - size - 0.5)), y = B + 16 + k * 16;
      var g = el("g", { opacity: 0 }, $("g-wins"));
      var line = el("path", { "class": "g-win" }, g);
      var name = w.stats.join(" AND ").toUpperCase() + ", " + size + (narrow ? " H" : " HOURS");
      var inside = x0 - L < 180;
      var lab = el("text", { x: inside ? x0 + 6 : x0 - 8, y: y + 4, "text-anchor": inside ? "start" : "end", "class": "g-winlab" }, g);
      lab.textContent = inside ? name : "ROLLING " + name;
      /* a window that starts near the left edge has no room for its label
         before it, so the label goes under the line (the last row) */
      if (inside) lab.setAttribute("y", y + 14);
      wins.push({ g: g, line: line, x0: x0, y: y });
    });
    function winD(w, p) {
      var xa = hzx - (hzx - w.x0) * p;
      return "M" + hzx.toFixed(1) + "," + (w.y - 4) + "V" + (w.y + 4) + "M" + hzx.toFixed(1) + "," + w.y +
        "H" + xa.toFixed(1) + (p >= 1 ? "M" + xa.toFixed(1) + "," + (w.y - 4) + "V" + (w.y + 4) : "");
    }

    /* ---------- side panes ---------- */
    $("f-nobs").textContent = ALL.profile.n_obs.toLocaleString("en-US");
    var pacfBox = $("pacf"), pacfFills = [];
    var SHOW_LAGS = 7, maxPacf = ALL.profile.pacf_abs[0];
    for (var q = 0; q < SHOW_LAGS; q++) {
      var lag = ALL.profile.pacf_lags[q], row = document.createElement("div");
      row.className = "pacf-row" + (lag === 25 || lag === 169 ? " season" : "");
      row.innerHTML = "<span>lag <b>" + lag + "</b></span><div><div class=\"fill\"></div></div><span>" +
        ALL.profile.pacf_abs[q].toFixed(2) + "</span>";
      pacfBox.appendChild(row);
      pacfFills.push({ el: row.querySelector(".fill"), w: ALL.profile.pacf_abs[q] / maxPacf * 100 });
    }
    var decisions = Array.prototype.slice.call(root.querySelectorAll(".decisions li"));
    $("m-mae").textContent = ALL.metrics.mae.toFixed(1);
    $("m-mase").textContent = ALL.metrics.mase.toFixed(2);
    var answer = $("answer"), answerText = answer.getAttribute("data-text");

    /* ---------- stage code ---------- */
    var CODE = [
      'from skforecast_ai import ForecastingAssistant\n\nassistant = ForecastingAssistant()  # no LLM needed\nprofile = assistant.profile(data, target="users", date_column="date_time")',
      'plan = assistant.plan(profile, steps=36, interval=[0.1, 0.9])\n\n# The plan is data: inspect it, override any field with refine_plan(),\n# or ask the LLM to refine the lags and window features.',
      "result = assistant.forecast(data, test_size=36, profile=profile, plan=plan)\n\n# result.code, the script that produced this forecast:\n\n" + ALL.code.trim(),
      'assistant = ForecastingAssistant(llm="google:gemini-3.5-flash")\nanswer = assistant.ask(\n    "Explain the evaluation metrics. Is the MASE good, and what do the predictions look like?",\n    context=result,\n)'
    ];
    var codeBox = $("stage-code-box"), codeEl = $("stage-code"), codeKey = null, codeTimer = null;
    function setCode(key) {
      if (key === codeKey) return;
      var first = codeKey === null;
      codeKey = key;
      clearTimeout(codeTimer);
      var apply = function () {
        codeEl.innerHTML = hl(CODE[key]);
        codeBox.classList.toggle("script", key === 2);
        codeBox.scrollTop = 0;
        codeEl.style.opacity = 1;
      };
      if (first || reduce) { apply(); return; }
      codeEl.style.opacity = 0;
      codeTimer = setTimeout(apply, 260);
    }

    /* ---------- timeline ---------- */
    var STEP_START = [0, 6000, 12500, 21500], S_END = 32000, TOTAL = S_END + 700;
    var STEP_END = [6000, 12500, 21500, S_END];
    var stepBtns = Array.prototype.slice.call(root.querySelectorAll(".step"));
    var panes = [$("pane-0"), $("pane-1"), $("pane-2"), $("pane-3")];
    var fcPath = $("g-fc"), bandPath = $("g-band"), histPath = $("g-hist"), actPath = $("g-act");
    var dot = $("g-dot"), leg = $("g-leg"), legdot = $("g-legdot"), dlab = $("g-dlab");
    if (narrow) dlab.textContent = "LightGBM";
    dlab.setAttribute("x", R - 4); dlab.setAttribute("y", T + 24); dlab.setAttribute("text-anchor", "end");
    /* the dot sits before the label, whose width changes once Poppins loads */
    function placeLegend() { legdot.setAttribute("cx", R - 15 - dlab.getComputedTextLength()); }
    legdot.setAttribute("cy", T + 19);
    placeLegend();
    if (document.fonts) document.fonts.ready.then(function () { if (!cancelled) placeLegend(); });
    var pred = [yv[te - 1]].concat(DATA.pred), lo = [yv[te - 1]].concat(DATA.lo), hi = [yv[te - 1]].concat(DATA.hi);
    function bandD(p) {
      var n = hzIdx.length, k = Math.max(1, Math.round(p * (n - 1)));
      var xs = hzIdx.slice(0, k + 1).map(sx);
      var up = hi.slice(0, k + 1).map(sy), dn = lo.slice(0, k + 1).map(sy);
      var d = "M" + xs[0].toFixed(1) + "," + up[0].toFixed(1);
      for (var j = 1; j < xs.length; j++) d += "L" + xs[j].toFixed(1) + "," + up[j].toFixed(1);
      for (var j2 = xs.length - 1; j2 >= 0; j2--) d += "L" + xs[j2].toFixed(1) + "," + dn[j2].toFixed(1);
      return d + "Z";
    }
    var curStep = -1;

    function render(t) {
      var step = t < STEP_START[1] ? 0 : t < STEP_START[2] ? 1 : t < STEP_START[3] ? 2 : 3;
      var u = t - STEP_START[step];
      if (step !== curStep) {
        curStep = step;
        panes.forEach(function (p, k) { p.classList.toggle("on", k === step); p.setAttribute("aria-hidden", k === step ? "false" : "true"); });
        stepBtns.forEach(function (b, k) { b.classList.toggle("on", k === step); if (k === step) b.setAttribute("aria-current", "step"); else b.removeAttribute("aria-current"); });
      }
      stepBtns.forEach(function (b, k) {
        var p = clamp01((t - STEP_START[k]) / (STEP_END[k] - STEP_START[k]));
        b.querySelector(".bar").style.width = (k === step ? p * 100 : 0) + "%";
      });
      svg.style.opacity = t > S_END ? 1 - clamp01((t - S_END) / 600) : clamp01(t / 450);
      setCode(step);

      /* the series: drawn in step 1, the held-out part dims from step 2 on */
      var hp = step === 0 ? ease(u / 2400) : 1;
      var split = histIdx.length / nAll;
      histPath.setAttribute("d", partial(histIdx, histVal, Math.min(1, hp / split)));
      actPath.setAttribute("d", hp > split ? partial(hzIdx, actVal, (hp - split) / (1 - split)) : "");
      var hzOn = step === 0 ? 0 : step === 1 ? clamp01((u - 200) / 600) : 1;
      actPath.setAttribute("opacity", 1 - 0.5 * hzOn);
      hz.setAttribute("opacity", hzOn); hzl.setAttribute("opacity", hzOn); hzlab.setAttribute("opacity", hzOn);

      /* profile: PACF bars and lag arcs */
      pacfFills.forEach(function (f, k) {
        f.el.style.width = (step === 0 ? ease((u - 1000 - k * 180) / 700) : 1) * f.w + "%";
      });
      arcs.forEach(function (a, k) {
        var p = step === 0 ? ease((u - 2600 - k * 700) / 1000) : 1;
        var op = step === 0 ? clamp01((u - 2600 - k * 700) / 200) : step === 1 ? 1 - clamp01(u / 400) : 0;
        a.path.setAttribute("d", p > 0 ? arcD(a, p) : "");
        a.dot.setAttribute("opacity", p >= 1 ? 1 : 0);
        a.lab.setAttribute("opacity", clamp01((p - 0.6) / 0.4));
        a.g.setAttribute("opacity", op);
      });

      /* plan: decisions and rolling windows */
      decisions.forEach(function (li, k) {
        li.classList.toggle("in", step > 1 || (step === 1 && u >= 300 + k * 600));
      });
      wins.forEach(function (w, k) {
        var p = step === 1 ? ease((u - 1500 - k * 700) / 900) : step > 1 ? 1 : 0;
        var op = step === 1 ? clamp01((u - 1500 - k * 700) / 200) : step === 2 ? 1 - clamp01(u / 400) : 0;
        w.line.setAttribute("d", p > 0 ? winD(w, p) : "");
        w.g.setAttribute("opacity", op);
      });

      /* run: forecast, interval and the generated script */
      var fp = step < 2 ? 0 : step === 2 ? ease((u - 300) / 2000) : 1;
      fcPath.setAttribute("d", partial(hzIdx, pred, fp));
      bandPath.setAttribute("d", fp > 0 ? bandD(fp) : "");
      dot.setAttribute("cx", sx(end)); dot.setAttribute("cy", sy(pred[pred.length - 1]));
      dot.setAttribute("opacity", fp >= 1 ? 1 : 0);
      leg.setAttribute("opacity", step < 2 ? 0 : step === 2 ? clamp01((u - 2300) / 350) : 1);
      if (step === 2 && codeKey === 2 && codeEl.style.opacity !== "0") {
        var room = codeBox.scrollHeight - codeBox.clientHeight;
        codeBox.scrollTop = room * ease((u - 1200) / 7000);
      }

      /* ask: the answer is typed */
      var nChars = step < 3 ? 0 : Math.round(clamp01((u - 900) / 6500) * answerText.length);
      if (answer.textContent.length !== nChars) answer.textContent = answerText.slice(0, nChars);
      answer.classList.toggle("typing", step === 3 && nChars < answerText.length);
    }

    var t0 = null, tNow = 0, playing = !reduce, visible = true, raf = null;
    var playBtn = $("play"), playIcon = $("play-icon");
    function setPlayUI() {
      playIcon.setAttribute("d", playing ? "M7 5h4v14H7zM13 5h4v14h-4z" : "M8 5v14l11-7z");
      playBtn.setAttribute("aria-label", playing ? "Pause animation" : "Play animation");
    }
    function frame(ts) {
      raf = null;
      if (cancelled || !playing || !visible) { t0 = null; return; }
      if (t0 === null) t0 = ts - tNow;
      tNow = (ts - t0) % TOTAL;
      if (ts - t0 >= TOTAL) t0 = ts - tNow;
      render(tNow);
      raf = requestAnimationFrame(frame);
    }
    function kick() { if (!cancelled && raf === null && playing && visible) raf = requestAnimationFrame(frame); }
    playBtn.addEventListener("click", function () { playing = !playing; t0 = null; setPlayUI(); kick(); });
    stepBtns.forEach(function (b, k) {
      b.addEventListener("click", function () {
        /* paused: show the step complete; playing: restart it */
        tNow = playing ? STEP_START[k] : STEP_END[k] - 1;
        t0 = null; render(tNow);
        if (!playing && k === 2) codeBox.scrollTop = 0;
        kick();
      });
    });
    if ("IntersectionObserver" in window) {
      var sio = new IntersectionObserver(function (entries) {
        visible = entries[0].isIntersecting; t0 = null; kick();
      }, { threshold: 0.1 });
      sio.observe($("stage"));
      observers.push(sio);
    }
    function onVisibility() { visible = !document.hidden; t0 = null; kick(); }
    document.addEventListener("visibilitychange", onVisibility);

    setPlayUI();
    /* resting frame: the complete last step when motion is reduced, the first frame otherwise */
    tNow = reduce ? S_END - 1 : 0;
    render(tNow);
    kick();

    /* ---------- generated script and snippets ---------- */
    $("script").innerHTML = hl(ALL.code.trim());
    copyButton($("copy-script"), ALL.code);
    Array.prototype.forEach.call(root.querySelectorAll("code[data-hl]"), function (c) {
      c.innerHTML = hl(c.textContent);
    });

    /* ---------- compare() leaderboard ---------- */
    var CMP = ALL.compare, board = $("board");
    var maxMae = Math.max.apply(null, CMP.rows.map(function (r) { return r.mae; }));
    board.innerHTML = '<div class="board-head" aria-hidden="true"><span>#</span><span>Candidate</span><span>MAE</span><span>MASE</span></div>';
    CMP.rows.forEach(function (r, k) {
      var row = document.createElement("div");
      row.className = "board-row" + (k === 0 ? " best" : "");
      row.style.setProperty("--w", (r.mae / maxMae * 100).toFixed(1) + "%");
      row.style.setProperty("--d", (k * 0.25).toFixed(2) + "s");
      row.innerHTML = '<span class="rank">' + (k + 1) + '</span><span class="who"><b>' + esc(r.name) +
        '</b><span class="fill"></span></span><span>' + r.mae.toFixed(2) + "</span><span>" + r.mase.toFixed(2) + "</span>";
      board.appendChild(row);
    });
    $("board-cap").innerHTML = "Real <code>compare()</code> output on the data of the animation, ranked by backtesting MAE (lower is better): " +
      esc(CMP.explanation.replace(/^Compared \d+ configurations, ranked ascending by \w+\. /, ""));
    if (reduce || !("IntersectionObserver" in window)) {
      board.classList.add("go");
    } else {
      var bio = new IntersectionObserver(function (e) {
        if (e[0].isIntersecting) { board.classList.add("go"); bio.disconnect(); }
      }, { threshold: 0.4 });
      bio.observe(board);
      observers.push(bio);
    }

    return {
      destroy: function () {
        cancelled = true;
        if (raf !== null) cancelAnimationFrame(raf);
        clearTimeout(codeTimer);
        timers.forEach(clearTimeout);
        observers.forEach(function (o) { o.disconnect(); });
        document.removeEventListener("visibilitychange", onVisibility);
      }
    };
  }

  function onDocument() {
    if (current) current.destroy();
    current = init();
  }
  if (typeof document$ !== "undefined") {
    document$.subscribe(onDocument);
  } else {
    document.addEventListener("DOMContentLoaded", onDocument);
  }
})();
